<?php
/** Member 2, Feature 4 - Fabric allocation history. */
require_once __DIR__.'/../../includes/auth.php'; require_role(['admin','production_manager']);
$pageTitle='Fabric Allocation & Traceability';$currentNav='fabric_allocations';$q=trim($_GET['q']??'');
$where='';$params=[];$types='';if($q!==''){$where=' WHERE fl.lot_number LIKE ? OR pb.batch_number LIKE ? OR bo.order_number LIKE ? OR s.supplier_name LIKE ?';$w='%'.$q.'%';$params=[$w,$w,$w,$w];$types='ssss';}
$sql="SELECT fa.*,fl.lot_number,fl.fabric_type,fl.unit,s.supplier_name,pb.batch_number,bo.order_number,bo.style_number,u.full_name allocator_name,u.username allocator_username FROM fabric_allocations fa JOIN fabric_lots fl ON fl.fabric_lot_id=fa.fabric_lot_id JOIN suppliers s ON s.supplier_id=fl.supplier_id JOIN production_batches pb ON pb.batch_id=fa.batch_id JOIN buyer_orders bo ON bo.order_id=pb.order_id JOIN users u ON u.user_id=fa.allocated_by{$where} ORDER BY fa.fabric_allocation_id DESC";
$rows=[];try{$stmt=$conn->prepare($sql);if(!$stmt)throw new Exception($conn->error);if($types)$stmt->bind_param($types,...$params);$stmt->execute();$rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();}catch(Throwable $e){error_log('Fabric allocation list failed: '.$e->getMessage());flash_set('error','Allocation records could not be loaded. Import sql/fabric_allocations.sql if the table is not installed.');}
include __DIR__.'/../../includes/header.php';include __DIR__.'/../../includes/sidebar.php';
?>
<div class="page-header"><div class="page-title-group"><h1>Fabric Allocation &amp; Traceability</h1><div class="page-subtitle">Member 2 &bull; Link approved fabric lots to production batches</div></div><div class="page-actions"><a class="btn btn-primary" href="<?=e(url('modules/fabric_allocations/create.php'))?>">Allocate Fabric</a><a class="btn btn-secondary" href="<?=e(url('modules/fabric_allocations/traceability.php'))?>">Trace a Lot</a></div></div>
<div class="card mb-4"><div class="card-body"><form method="get" class="filter-bar"><div class="filter-field-grow"><label class="form-label" for="q">Search Allocation History</label><input class="form-control" id="q" name="q" value="<?=e($q)?>" placeholder="Lot, batch, order, or supplier"></div><div class="filter-actions"><button class="btn btn-primary">Search</button><?php if($q!==''):?><a class="btn btn-secondary" href="<?=e(url('modules/fabric_allocations/index.php'))?>">Clear</a><?php endif?></div></form></div></div>
<div class="card"><div class="card-header"><h2>Allocation History</h2><span class="badge badge-muted"><?=count($rows)?> Record(s)</span></div><div class="card-body" style="padding:0"><?php if(!$rows):?><div class="empty-state"><p>No fabric allocations found.</p><a class="btn btn-primary btn-sm" href="<?=e(url('modules/fabric_allocations/create.php'))?>">Create First Allocation</a></div><?php else:?><div class="table-responsive"><table class="table"><thead><tr><th>Lot</th><th>Supplier</th><th>Production Batch</th><th>Order / Style</th><th>Quantity</th><th>Date</th><th>Allocated By</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['lot_number'])?></strong><div class="text-xs text-muted"><?=e($r['fabric_type'])?></div></td><td><?=e($r['supplier_name'])?></td><td><strong><?=e($r['batch_number'])?></strong></td><td><?=e($r['order_number'])?><div class="text-xs text-muted"><?=e($r['style_number'])?></div></td><td><strong><?=number_format((float)$r['allocated_quantity'],2)?> <?=e($r['unit'])?></strong></td><td><?=e(date('M d, Y',strtotime($r['allocated_date'])))?></td><td><?=e($r['allocator_name']?:$r['allocator_username'])?></td><td><a class="btn btn-sm btn-secondary" href="<?=e(url('modules/fabric_allocations/view.php?id='.(int)$r['fabric_allocation_id']))?>">View</a></td></tr><?php endforeach?></tbody></table></div><?php endif?></div></div>
<?php echo '<link rel="stylesheet" href="modern-ui.css">'; include __DIR__.'/../../includes/footer.php';
